#!/usr/bin/env bash
# Builds the tvOS app, signs it for the App Store, validates it with App Store Connect and, if
# that succeeds, uploads it (to TestFlight / App Store Connect). Everything is generated by
# CMake (Xcode generator); no hand-made Xcode project is involved. Modeled on the owner's iOS
# deployment scripts (Umsci: Resources/Deployment/iOS/buildAndExport_Umsci.sh).
#
# usage: scripts/package-tvos.sh <apple-id> [team-id]
#   apple-id   the Apple ID used for App Store Connect, e.g. you@example.com
#   team-id    developer team ID (10 characters). Default: DIORASCII_APPLE_TEAM, else taken from
#              your "Apple Distribution" or "Developer ID Application" certificate in the keychain.
#
# One-time setup (same keychain item as the Umsci script):
#   xcrun altool --store-password-in-keychain-item "AppSpecificPW" -u <apple-id> -p <app-specific password>
#   and the app record for com.ChristianAhrens.Diorascii in App Store Connect (platform tvOS).
#
# environment:
#   DIORASCII_APPLE_TEAM          team ID (see above)
#   DIORASCII_APP_PASSWORD_ITEM   keychain item with the app-specific password (default AppSpecificPW)
#   DIORASCII_BUILD_NUMBER        CFBundleVersion; must grow with every upload of one version.
#                                 Default: the number of commits on the current branch.
#   DIORASCII_PROFILE             name of the installed App Store distribution profile (default
#                                 "Diorascii tvOS distribution profile"). If it is installed (double-click the
#                                 downloaded .mobileprovision once) the app is signed manually with it and the
#                                 matching Apple Distribution certificate, which needs no registered Apple TV.
#                                 Without it, automatic signing is used, which does need one.
#   DIORASCII_SKIP_UPLOAD=1       build, export and validate, but do not upload
#   DIORASCII_SKIP_VALIDATE=1     do not validate (the upload validates anyway)
#
# The marketing version is the latest released section of CHANGELOG.md. Output: dist/tvos/.
set -euo pipefail
cd "$(dirname "$0")/.."

appleId="${1:-}"
[ -n "$appleId" ] || { echo "usage: $0 <apple-id> [team-id]" >&2; exit 2; }
[ "$(uname -s)" = Darwin ] || { echo "error: this script runs on macOS with Xcode" >&2; exit 1; }
command -v xcodebuild >/dev/null || { echo "error: xcodebuild not found (install Xcode)" >&2; exit 1; }

team="${2:-${DIORASCII_APPLE_TEAM:-}}"
if [ -z "$team" ]; then
  # "Apple Distribution: Name (TEAMID)", or the Developer ID certificate, which carries the same team
  team="$(security find-identity -v -p codesigning \
    | sed -n 's/.*"\(Apple Distribution\|Developer ID Application\):.*(\([A-Z0-9]\{10\}\))".*/\2/p' | head -n 1)"
fi
[ -n "$team" ] || { echo "error: no team ID: pass it as the second argument or set DIORASCII_APPLE_TEAM" >&2; exit 1; }

passwordItem="${DIORASCII_APP_PASSWORD_ITEM:-AppSpecificPW}"
buildNumber="${DIORASCII_BUILD_NUMBER:-$(git rev-list --count HEAD)}"
version="$(scripts/release-notes.sh --latest)"
build="build/package-tvos"
out="dist/tvos"
archive="$build/Diorascii.xcarchive"
ipa="$out/Diorascii.ipa"

# Looks for an installed provisioning profile with the given name and prints its path.
findProfile() {
  local dir f
  for dir in "$HOME/Library/Developer/Xcode/UserData/Provisioning Profiles" "$HOME/Library/MobileDevice/Provisioning Profiles"; do
    [ -d "$dir" ] || continue
    for f in "$dir"/*.mobileprovision; do
      [ -f "$f" ] || continue
      if [ "$(security cms -D -i "$f" 2>/dev/null | plutil -extract Name raw -o - - 2>/dev/null)" = "$1" ]; then
        printf '%s\n' "$f"
        return 0
      fi
    done
  done
  return 1
}

# The SHA-1 of the certificate in the profile that is also in the keychain (there may be several
# "Apple Distribution" certificates with the same name).
profileIdentity() {
  local plist n i sha
  plist="$(security cms -D -i "$1")"
  n="$(printf '%s' "$plist" | plutil -extract DeveloperCertificates raw -o - -)"
  for i in $(seq 0 $((n - 1))); do
    sha="$(printf '%s' "$plist" | plutil -extract "DeveloperCertificates.$i" raw -o - - | base64 -d \
      | openssl x509 -inform der -noout -fingerprint -sha1 | sed 's/.*=//; s/://g')"
    if security find-identity -v -p codesigning | grep -q "$sha"; then
      printf '%s\n' "$sha"
      return 0
    fi
  done
  return 1
}

profileName="${DIORASCII_PROFILE:-Diorascii tvOS distribution profile}"
signingArgs=()
signingStyle=automatic
exportProfiles=""
if profileFile="$(findProfile "$profileName")"; then
  identity="$(profileIdentity "$profileFile")" || {
    echo "error: the certificate of profile '$profileName' is not in your keychain" >&2; exit 1; }
  signingStyle=manual
  signingArgs=("-DDIORASCII_PROVISIONING_PROFILE=$profileName" "-DDIORASCII_SIGN_IDENTITY=$identity")
  exportProfiles="  <key>signingCertificate</key><string>$identity</string>
  <key>provisioningProfiles</key><dict><key>com.ChristianAhrens.Diorascii</key><string>$profileName</string></dict>"
  echo "== signing manually with profile '$profileName' and certificate $identity"
else
  echo "== profile '$profileName' is not installed: automatic signing (needs a registered Apple TV)"
fi

echo "== tvOS $version ($buildNumber), team $team"
if [ -n "$(git status --porcelain --untracked-files=no)" ]; then
  echo "warning: the working tree has uncommitted changes; they are part of this build" >&2
fi

echo "== configure"
rm -rf "$build"
cmake -S . -B "$build" -G Xcode -DCMAKE_SYSTEM_NAME=tvOS -DCMAKE_OSX_SYSROOT=appletvos \
  "-DDIORASCII_APPLE_TEAM=$team" "-DDIORASCII_BUILD_NUMBER=$buildNumber" \
  "-DDIORASCII_VERSION=$version" ${signingArgs[@]+"${signingArgs[@]}"}

echo "== archive"
xcodebuild -project "$build/diorascii.xcodeproj" -scheme Diorascii -configuration Release \
  -destination generic/platform=tvOS -archivePath "$archive" \
  $([ "$signingStyle" = automatic ] && echo -allowProvisioningUpdates) \
  DEVELOPMENT_TEAM="$team" clean archive

echo "== export"
rm -rf "$out"
mkdir -p "$out"
exportOptions="$build/exportOptions.plist"
cat > "$exportOptions" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>method</key><string>app-store-connect</string>
  <key>teamID</key><string>$team</string>
  <key>signingStyle</key><string>$signingStyle</string>
$exportProfiles
  <key>destination</key><string>export</string>
  <key>uploadSymbols</key><true/>
</dict>
</plist>
PLIST
xcodebuild -exportArchive -archivePath "$archive" -exportOptionsPlist "$exportOptions" \
  -exportPath "$out" $([ "$signingStyle" = automatic ] && echo -allowProvisioningUpdates)
[ -f "$ipa" ] || { echo "error: export did not produce $ipa" >&2; exit 1; }

if [ -z "${DIORASCII_SKIP_VALIDATE:-}" ]; then
  echo "== validate with App Store Connect"
  xcrun altool --validate-app -f "$ipa" --type appletvos \
    --username "$appleId" --password "@keychain:$passwordItem"
fi

if [ -n "${DIORASCII_SKIP_UPLOAD:-}" ]; then
  echo "== done: $ipa (not uploaded)"
else
  echo "== upload"
  xcrun altool --upload-app -f "$ipa" --type appletvos \
    --username "$appleId" --password "@keychain:$passwordItem"
  echo "== done: Diorascii $version ($buildNumber) uploaded; it shows up in App Store Connect / TestFlight after processing"
fi
